const journalReaderProbeEffect = "journal-reader-probe"

type journalReaderImage struct {
	Path        string `json:"path"`
	SHA256      string `json:"sha256"`
	ReadVersion int    `json:"read_version"`
}

// Embedded in the existing immutable file review and covered by its digest.
// Paths are generated by the fixed inventory, never supplied by a client.
type journalReaderProof struct {
	Schema         int                  `json:"schema"`
	RequiredReader int                  `json:"required_reader"`
	Controllers    []journalReaderImage `json:"controllers"`
}

func validJournalReaderProof(proof *journalReaderProof) bool {
	if proof == nil || (proof.Schema != selfupdatejournal.StoppedSchema && proof.Schema != SelfUpdateReadVersion) || proof.RequiredReader != proof.Schema || len(proof.Controllers) == 0 || len(proof.Controllers) > 1024 {
		return false
	}
	previous := ""
	for _, image := range proof.Controllers {
		if !filepath.IsAbs(image.Path) || image.Path != filepath.Clean(image.Path) || image.Path <= previous || !validDigest("sha256:"+image.SHA256) || image.ReadVersion != proof.RequiredReader {
			return false
		}
		previous = image.Path
	}
	return true
}

func boundedJobDirectories(directory string) ([]os.DirEntry, error) {
	root, err := os.OpenRoot(directory)
	if err != nil {
		return nil, err
	}
	defer root.Close()
	f, err := root.Open(".")
	if err != nil {
		return nil, err
	}
	defer f.Close()
	entries, err := f.ReadDir(258)
	if err != nil && err != io.EOF {
		return nil, err
	}
	if len(entries) > 257 {
		return nil, ErrFileProtocol
	}
	return entries, nil
}

func (a *SelfUpdateFileAdapter) journalReaderImages(ctx context.Context, review fileReview) ([]selfupdatejournal.BinaryImage, error) {
	return a.journalReaderImagesWithCurrent(ctx, review, review.OldExecutableSHA256)
}

// A component writer observes the actually installed controller after a
// terminal upgrade, while Prepare observes the pre-upgrade reviewed image.
// Both use the same concrete helper/candidate/retained inventory and seals.
func (a *SelfUpdateFileAdapter) journalReaderImagesWithCurrent(ctx context.Context, review fileReview, currentSHA string) ([]selfupdatejournal.BinaryImage, error) {
	if a == nil || a.owned == nil || !jobIDPattern.MatchString(review.ID) {
		return nil, ErrFileProtocol
	}
	images := []selfupdatejournal.BinaryImage{{Path: filepath.Join(a.installation, "bin/razvilka"), SHA256: currentSHA}}
	entries, err := boundedJobDirectories(a.directory)
	if err != nil {
		return nil, err
	}
	found := false
	for _, entry := range entries {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		if entry.Name() == "current.json" {
			root, err := ownedfs.Open(a.directory)
			if err != nil {
				return nil, err
			}
			data, err := root.ReadLimited("current.json", 64<<10)
			root.Close()
			var record updateRecord
			if err != nil || decodeFileProtocol(data, &record) != nil || record.Owner != updaterOwner || record.Job.ID != review.ID {
				return nil, ErrFileProtocol
			}
			continue
		}
		if !entry.IsDir() || entry.Type()&os.ModeSymlink != 0 || !jobIDPattern.MatchString(entry.Name()) {
			return nil, ErrFileProtocol
		}
		r := review
		if entry.Name() != review.ID {
			var record updateRecord
			record, r, err = a.loadBoundReview(ctx, entry.Name(), true, true)
			if err != nil {
				return nil, err
			}
			if err := a.checkRetainedHelperFile(ctx, record, r); err != nil {
				return nil, err
			}
		} else {
			found = true
			// The one known helper publication cut may leave retained terminal
			// metadata before current. It must bind to this exact review/file
			// receipt; an unrelated copied or orphan archive is not ignored.
			root, err := a.commandRoot(review.ID)
			if err != nil {
				return nil, err
			}
			_, archiveErr := root.Stat("retained-helper.json")
			root.Close()
			if archiveErr == nil {
				record, retainedReview, err := a.loadBoundReview(ctx, review.ID, true, true)
				if err != nil || !reflect.DeepEqual(retainedReview, review) {
					return nil, errors.Join(ErrFileProtocol, err)
				}
				if err := a.checkRetainedHelperFile(ctx, record, retainedReview); err != nil {
					return nil, err
				}
			} else if !errors.Is(archiveErr, os.ErrNotExist) {
				return nil, archiveErr
			}
		}
		retired := false
		if _, err := os.Lstat(a.fileJournal); err == nil {
			store, err := a.OpenFileJournal()
			if err != nil {
				return nil, err
			}
			fileReceipt, receiptErr := store.RetainedReceipt(ctx, r.ID)
			store.Close()
			if receiptErr != nil && !errors.Is(receiptErr, os.ErrNotExist) {
				return nil, receiptErr
			}
			retired = receiptErr == nil && fileReceipt.Phase == "archived"
		} else if !errors.Is(err, os.ErrNotExist) {
			return nil, err
		}
		if !retired {
			images = append(images, selfupdatejournal.BinaryImage{Path: filepath.Join(a.directory, r.ID, "control.bin"), SHA256: reviewedHelperSHA(r)})
		}
		binaries := 0
		for _, file := range r.Files {
			if file.Target == "bin/razvilka" {
				binaries++
				if !retired {
					images = append(images, selfupdatejournal.BinaryImage{Path: file.Candidate, SHA256: file.SHA256})
				}
			}
		}
		if binaries != 1 {
			return nil, ErrFileProtocol
		}
	}
	if !found {
		return nil, ErrFileProtocol
	}
	if _, err := os.Lstat(a.fileJournal); err == nil {
		store, err := a.OpenFileJournal()
		if err != nil {
			return nil, err
		}
		retained, err := store.RetainedBinaryImagesForSettlement(ctx, review.ID)
		store.Close()
		if err != nil {
			return nil, err
		}
		candidateSHA := ""
		for _, file := range review.Files {
			if file.Target == "bin/razvilka" {
				candidateSHA = file.SHA256
			}
		}
		for _, image := range retained {
			if filepath.Dir(image.Path) == filepath.Join(a.fileJournal, review.ID) {
				// These snapshots are made after review. Their bytes must match
				// the already probed old/candidate controllers exactly.
				if image.SHA256 != review.OldExecutableSHA256 && image.SHA256 != candidateSHA {
					return nil, ErrFileProtocol
				}
				continue
			}
			images = append(images, image)
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	legacy := filepath.Join(filepath.Dir(a.directory), "update-backups")
	if _, err := os.Lstat(legacy); err == nil {
		entries, err := boundedJobDirectories(legacy)
		if err != nil {
			return nil, err
		}
		root, err := ownedfs.Open(legacy)
		if err != nil {
			return nil, err
		}
		defer root.Close()
		for _, entry := range entries {
			if !entry.IsDir() || entry.Type()&os.ModeSymlink != 0 {
				return nil, ErrFileProtocol
			}
			name := filepath.Join(entry.Name(), "razvilka.bin")
			if _, err := root.Stat(name); errors.Is(err, os.ErrNotExist) {
				continue
			} else if err != nil {
				return nil, err
			}
			sha, err := root.ReadLimited(filepath.Join(entry.Name(), "razvilka.sha256"), 64)
			if err != nil || !validDigest("sha256:"+string(sha)) {
				return nil, ErrFileProtocol
			}
			images = append(images, selfupdatejournal.BinaryImage{Path: filepath.Join(legacy, name), SHA256: string(sha)})
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	if len(images) > 1024 {
		return nil, ErrFileProtocol
	}
	sort.Slice(images, func(i, j int) bool { return images[i].Path < images[j].Path })
	for i, image := range images {
		if i > 0 && image.Path == images[i-1].Path {
			return nil, ErrFileProtocol
		}
		if err := a.owned(image.Path); err != nil {
			return nil, err
		}
		root, err := ownedfs.Open(filepath.Dir(image.Path))
		if err != nil {
			return nil, err
		}
		data, err := root.ReadLimited(filepath.Base(image.Path), MaximumBinaryBytes)
		root.Close()
		if err != nil || digestBytes(data) != image.SHA256 {
			return nil, ErrFileProtocol
		}
	}
	return images, ctx.Err()
}

func (a *SelfUpdateFileAdapter) sealJournalReaders(ctx context.Context, review fileReview, authority func(context.Context, string) (SelfUpdateAuthority, error)) (*journalReaderProof, error) {
	return a.sealJournalReadersWithProbe(ctx, review, authority, a.probeJournalReader)
}

func (a *SelfUpdateFileAdapter) sealJournalReadersWithProbe(ctx context.Context, review fileReview, authority func(context.Context, string) (SelfUpdateAuthority, error), probe func(context.Context, fileReview, selfupdatejournal.BinaryImage) (int, error)) (*journalReaderProof, error) {
	proof, err := a.sealOptionalJournalReadersWithProbe(ctx, review, authority, probe)
	if err == nil && proof == nil {
		return nil, ErrStoppedSettlementIneligible
	}
	return proof, err
}

// Ordinary schema2 live Prepare keeps its existing capability2 guards. A
// positively observed reader2 makes this review explicitly stopped-ineligible;
// it never manufactures reader3 proof. Unknown/corrupt/future evidence refuses
// the preparation rather than borrowing this compatibility path.
func (a *SelfUpdateFileAdapter) sealOptionalJournalReadersWithProbe(ctx context.Context, review fileReview, authority func(context.Context, string) (SelfUpdateAuthority, error), probe func(context.Context, fileReview, selfupdatejournal.BinaryImage) (int, error)) (*journalReaderProof, error) {
	if authority == nil || probe == nil || a.admission == nil {
		return nil, ErrFileProtocol
	}
	check := func() error {
		value, err := authority(ctx, review.ID)
		if err != nil || value.InstallationID != review.AuthorityInstallationID || value.Sequence != review.AuthoritySequence {
			return errors.Join(ErrFileProtocol, err)
		}
		return ctx.Err()
	}
	if err := check(); err != nil {
		return nil, err
	}
	images, err := a.journalReaderImages(ctx, review)
	if err != nil {
		return nil, err
	}
	required, err := a.requiredJournalReadVersion(ctx)
	if err != nil {
		return nil, err
	}
	// A new reader4 still reads the unchanged stopped3 declaration. Ordinary
	// preparation does not demand reader4 merely because its binary supports it.
	proof := &journalReaderProof{Schema: selfupdatejournal.StoppedSchema, RequiredReader: selfupdatejournal.StoppedSchema}
	eligible := true
	observedVersion := 0
	for _, image := range images {
		if err := check(); err != nil {
			return nil, err
		}
		version, err := probe(ctx, review, image)
		if err != nil || version < selfUpdateProtocolSchema || version > SelfUpdateReadVersion {
			return nil, errors.Join(ErrFileProtocol, err)
		}
		// Keep the accepted ordinary2 compatibility path. Paired active
		// evidence is a distinct version4 format and cannot borrow that path.
		if required >= selfupdatejournal.PairedSchema && version < required {
			return nil, ErrFileProtocol
		}
		if version == selfUpdateProtocolSchema {
			eligible = false
		}
		if observedVersion != 0 && observedVersion != version {
			eligible = false
		}
		observedVersion = version
		proof.Controllers = append(proof.Controllers, journalReaderImage{image.Path, image.SHA256, version})
	}
	if err := check(); err != nil {
		return nil, err
	}
	fresh, err := a.journalReaderImages(ctx, review)
	if err != nil || !reflect.DeepEqual(images, fresh) {
		return nil, errors.Join(ErrFileProtocol, err)
	}
	if !eligible {
		return nil, nil
	}
	proof.Schema, proof.RequiredReader = observedVersion, observedVersion
	return proof, nil
}

func (a *SelfUpdateFileAdapter) probeJournalReader(ctx context.Context, review fileReview, image selfupdatejournal.BinaryImage) (int, error) {
	if a.admission == nil {
		return 0, ErrFileProtocol
	}
	root, err := ownedfs.Open(filepath.Dir(image.Path))
	if err != nil {
		return 0, err
	}
	data, err := root.ReadLimited(filepath.Base(image.Path), MaximumBinaryBytes)
	root.Close()
	if err != nil || digestBytes(data) != image.SHA256 {
		return 0, ErrFileProtocol
	}
	temporary, err := os.MkdirTemp("", "razvilka-journal-reader-")
	if err != nil {
		return 0, err
	}
	defer os.Remove(temporary)
	path := filepath.Join(temporary, "controller")
	defer os.Remove(path)
	if err := os.WriteFile(path, data, 0700); err != nil {
		return 0, err
	}
	probeCtx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()
	run := func(flag string) (stdout, stderr string, waitErr, admissionErr error) {
		command := exec.CommandContext(probeCtx, path, flag)
		command.Env = commandEnvironment()
		output, diagnostic := &cappedOutput{maximum: 16}, &cappedOutput{maximum: 4096}
		command.Stdout, command.Stderr = output, diagnostic
		configureBoundedCommand(command)
		_, done, err := startInstallerHelperCommand(probeCtx, command, func(begin func() error) error {
			return a.admission(probeCtx, review.ID, review.AuthorityInstallationID, review.AuthoritySequence, "start/live", journalReaderProbeEffect, begin)
		})
		if done == nil {
			return "", "", nil, err
		}
		if err != nil {
			cancel()
			cleanupCommand(command)
		}
		waitErr = <-done
		return output.String(), diagnostic.String(), waitErr, err
	}
	stdout, stderr, waitErr, admissionErr := run("-self-update-read-version")
	legacy := false
	if admissionErr != nil {
		return 0, errors.Join(ErrFileProtocol, admissionErr, waitErr)
	}
	if waitErr != nil {
		var exited *exec.ExitError
		// Old Go flag parsers explicitly refuse the new flag. Only this
		// known ABI response allows a second positive legacy capability2
		// observation. Panic/timeout/signals/garbage never downgrade.
		if !errors.As(waitErr, &exited) || exited.ExitCode() != 2 || stdout != "" || !strings.HasPrefix(stderr, "flag provided but not defined: -self-update-read-version\n") || probeCtx.Err() != nil {
			return 0, errors.Join(ErrFileProtocol, waitErr)
		}
		legacy = true
		stdout, stderr, waitErr, admissionErr = run("-self-update-schema")
		if waitErr != nil || admissionErr != nil || stderr != "" {
			return 0, errors.Join(ErrFileProtocol, waitErr, admissionErr)
		}
	}
	version, err := parseJournalReaderVersion(stdout, stderr, legacy)
	if err != nil {
		return 0, err
	}
	return version, ctx.Err()
}

func parseJournalReaderVersion(stdout, stderr string, legacy bool) (int, error) {
	value := strings.TrimSuffix(stdout, "\n")
	version, err := strconv.Atoi(value)
	if err != nil || stdout != strconv.Itoa(version)+"\n" || version < 1 || version > SelfUpdateReadVersion || legacy && version != selfUpdateProtocolSchema || stderr != "" {
		return 0, ErrFileProtocol
	}
	return version, nil
}

// Read-only settlement consumer. Missing/old/future proof or any inventory or
// digest drift refuses. This path never executes a version probe after Stop.
func (a *SelfUpdateFileAdapter) CheckRetainedJournalReaders(ctx context.Context, id string, wanted int) error {
	if wanted < selfupdatejournal.StoppedSchema || wanted > SelfUpdateReadVersion {
		return ErrFileProtocol
	}
	record, review, err := a.load(ctx, id)
	if err != nil {
		return err
	}
	if err := a.checkHelperProcessFormats(ctx, record, review); err != nil {
		return err
	}
	if !validJournalReaderProof(review.JournalReaders) {
		if review.JournalReaders == nil {
			return ErrStoppedSettlementIneligible
		}
		return ErrFileProtocol
	}
	images, err := a.journalReaderImages(ctx, review)
	if err != nil {
		return err
	}
	if len(images) != len(review.JournalReaders.Controllers) {
		return ErrFileProtocol
	}
	for i, image := range images {
		proof := review.JournalReaders.Controllers[i]
		if image.Path != proof.Path || image.SHA256 != proof.SHA256 || proof.ReadVersion < wanted {
			return ErrFileProtocol
		}
	}
	return ctx.Err()
}

// Immutable review declaration only, never effect authority. False is explicit
// stopped ineligibility for a legacy/ordinary schema2 review. Even true still
// requires CheckRetainedJournalReaders and exact preserved Stop at settlement.
func (a *SelfUpdateFileAdapter) StoppedSettlementEligibility(ctx context.Context, id string) (bool, error) {
	_, review, err := a.load(ctx, id)
	if err != nil {
		return false, err
	}
	if review.JournalReaders == nil {
		return false, nil
	}
	if !validJournalReaderProof(review.JournalReaders) {
		return false, ErrFileProtocol
	}
	return true, ctx.Err()
}

// CORE's downgrade reader CLI supplies fixed startup paths. It performs no
// migration, journal mutation, process start, Stop reset or live Store open.
func RequiredSelfUpdateJournalReadVersion(ctx context.Context, installation, helperDirectory, fileJournal string) (int, error) {
	if !filepath.IsAbs(installation) || !filepath.IsAbs(helperDirectory) || !filepath.IsAbs(fileJournal) {
		return 0, ErrFileProtocol
	}
	a := NewSelfUpdateFileAdapter()
	a.installation, a.directory, a.fileJournal = installation, helperDirectory, fileJournal
	return a.requiredJournalReadVersion(ctx)
}

func (a *SelfUpdateFileAdapter) requiredJournalReadVersion(ctx context.Context) (int, error) {
	required := 1
	if _, err := os.Lstat(a.fileJournal); err == nil {
		if err := a.owned(a.fileJournal); err != nil {
			return 0, err
		}
		store, err := a.OpenFileJournal()
		if err != nil {
			return 0, err
		}
		required, err = store.RequiredReadVersion(ctx)
		store.Close()
		if err != nil {
			return 0, err
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return 0, err
	}
	if _, err := os.Lstat(a.directory); errors.Is(err, os.ErrNotExist) {
		return required, ctx.Err()
	} else if err != nil {
		return 0, err
	}
	if err := a.owned(a.directory); err != nil {
		return 0, err
	}
	entries, err := boundedJobDirectories(a.directory)
	if err != nil {
		return 0, err
	}
	root, err := ownedfs.Open(a.directory)
	if err != nil {
		return 0, err
	}
	defer root.Close()
	data, err := root.ReadLimited("current.json", 64<<10)
	if err != nil {
		return 0, err
	}
	var current updateRecord
	if decodeFileProtocol(data, &current) != nil || current.Owner != updaterOwner || !jobIDPattern.MatchString(current.Job.ID) {
		return 0, ErrFileProtocol
	}
	preparing, err := a.preparingHelper(ctx, current)
	if err != nil {
		return 0, err
	}
	found := preparing && current.Job.Stage == "metadata"
	for _, entry := range entries {
		if err := ctx.Err(); err != nil {
			return 0, err
		}
		if entry.Name() == "current.json" {
			continue
		}
		if !entry.IsDir() || entry.Type()&os.ModeSymlink != 0 || !jobIDPattern.MatchString(entry.Name()) {
			return 0, ErrFileProtocol
		}
		retained := entry.Name() != current.Job.ID
		if !retained && preparing {
			found = true
			if required < selfUpdateProtocolSchema {
				required = selfUpdateProtocolSchema
			}
			continue
		}
		record, review, err := a.loadBoundReview(ctx, entry.Name(), true, retained)
		if err != nil {
			return 0, err
		}
		if !retained {
			found = true
		}
		if required < selfUpdateProtocolSchema {
			required = selfUpdateProtocolSchema
		}
		if required < review.Schema {
			required = review.Schema
		}
		if review.JournalReaders != nil {
			if !validJournalReaderProof(review.JournalReaders) {
				return 0, ErrFileProtocol
			}
			if required < review.JournalReaders.RequiredReader {
				required = review.JournalReaders.RequiredReader
			}
		}
		if record.Job.State == stoppedRollbackState && review.JournalReaders == nil {
			return 0, ErrFileProtocol
		}
		if terminalHelperState(record.Job.State) {
			if err := a.checkRetainedHelperFile(ctx, record, review); err != nil {
				return 0, err
			}
		} else if err := a.checkHelperProcessFormats(ctx, record, review); err != nil {
			return 0, err
		}
	}
	if !found {
		return 0, ErrFileProtocol
	}
	return required, ctx.Err()
}

func (a *SelfUpdateFileAdapter) checkRetainedHelperFile(ctx context.Context, record updateRecord, review fileReview) error {
	if err := a.checkHelperProcessFormats(ctx, record, review); err != nil {
		return err
	}
	store, err := a.OpenFileJournal()
	if err != nil {
		return err
	}
	defer store.Close()
	r, err := store.RetainedReceipt(ctx, review.ID)
	if err != nil {
		return err
	}
	wanted := "accepted"
	if record.Job.State == "rolled-back" {
		wanted = "rolled-back"
	}
	if record.Job.State == stoppedRollbackState {
		wanted = stoppedRollbackState
	}
	if r.Pending() || (r.Phase != wanted && !(wanted == "accepted" && r.Phase == "archived")) || r.Rollback != (record.Job.State != "completed") {
		return ErrFileProtocol
	}
	if wanted == stoppedRollbackState && (r.Stopped == nil || r.Stopped.InstallationID != review.AuthorityInstallationID || r.Stopped.PreStopSequence != review.AuthoritySequence || r.Stopped.Revision != review.Revision || !validJournalReaderProof(review.JournalReaders)) {
		return ErrFileProtocol
	}
	return store.VerifyReviewedImages(ctx, review.ID, review.Files, review.OldExecutableSHA256, review.OldInitSHA256, review.OldConfigSHA256)
}

func (a *SelfUpdateFileAdapter) checkHelperProcessFormats(ctx context.Context, record updateRecord, review fileReview) error {
	entries, err := boundedJobDirectories(filepath.Join(a.directory, review.ID))
	if err != nil {
		return err
	}
	root, err := a.commandRoot(review.ID)
	if err != nil {
		return err
	}
	defer root.Close()
	for _, entry := range entries {
		if err := ctx.Err(); err != nil {
			return err
		}
		if strings.HasSuffix(entry.Name(), ".process.json") {
			command := strings.TrimSuffix(entry.Name(), ".process.json")
			if !validFileCommand(command) {
				return ErrFileProtocol
			}
			if _, err := readFileCommand(root, review.ID, command); err != nil {
				return err
			}
		}
	}
	data, err := root.ReadLimited("helper.identity.json", 4096)
	if err == nil {
		var identity fileHelperIdentity
		if decodeFileProtocol(data, &identity) != nil || identity.Schema != selfUpdateProtocolSchema || identity.ID != review.ID || !validFileProcess(identity.Process) || !validFileProcess(identity.OldPanel) || identity.Process.ExecutableSHA256 != reviewedHelperSHA(review) || identity.OldPanel.ExecutableSHA256 != review.OldExecutableSHA256 || identity.Process.Boot != identity.OldPanel.Boot || identity.Process.PID != record.Job.HelperPID || identity.OldPanel.PID != record.ParentPID || review.PreparationParent != nil && *review.PreparationParent != identity.OldPanel {
			return ErrFileProtocol
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return err
	}
	if _, err := root.Stat("private-snapshot.json"); err == nil {
		if _, err := a.privateSnapshot(ctx, review.ID); err != nil {
			return err
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return err
	}
	if data, err := root.ReadLimited("private-restore/restore.private.json", 12<<20); err == nil {
		if err := inspectRetainedRestoreNodes(data, func([]byte) error { return nil }); err != nil {
			return err
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return err
	}
	return ctx.Err()
}
